void test_studio_host_json_updates_report_settings_memos_by_stable_selection(
    const std::string& studio_host_path) {
    namespace fs = std::filesystem;

    const fs::path temp_root =
        fs::temp_directory_path() / "copperfin_studio_host_report_settings_memo_stable_json_tests";
    std::error_code ignored;
    fs::remove_all(temp_root, ignored);
    fs::create_directories(temp_root);

    const std::string updated_settings =
        "ORIENTATION=1\n"
        "PAPERSIZE=9\n"
        "BOTMARGIN=32\n"
        "GRIDV=6\n"
        "GRIDH=10\n"
        "TOPMARGIN=14";

    const auto run_settings_update = [&](const fs::path& asset_path,
                                         const std::string& title,
                                         const std::string& label) {
        write_synthetic_report_table_for_stable_settings_json(asset_path);
        const auto update_process = run_process_capture(
            studio_host_path,
            {
                "--path", asset_path.string(),
                "--set-property",
                "--unique-id", "settings-guid",
                "--property-name", "EXPR",
                "--property-value", updated_settings,
                "--json"
            },
            temp_root);

        if (update_process.exit_code != 0) {
            std::cerr << "studio host " << label << " stable settings memo update stdout:\n"
                      << update_process.stdout_text << "\n";
            std::cerr << "studio host " << label << " stable settings memo update stderr:\n"
                      << update_process.stderr_text << "\n";
            std::cerr << "fixture root: " << temp_root << "\n";
        }

        expect(update_process.exit_code == 0,
               "#1826: report/label stable settings memo update should exit successfully");
        const auto expr_property = copperfin::vfp::query_visual_object_property({
            .path = asset_path.string(),
            .record_index = 0U,
            .object_name = {},
            .unique_id = "settings-guid",
            .property_name = "EXPR"
        });
        expect(expr_property.ok && expr_property.exists && expr_property.value == updated_settings,
               "#1826: report/label stable settings memo update should persist the EXPR memo field");
        expect_contains(update_process.stdout_text, "\"documentTitle\": \"" + title + "\"",
                        "#1826: report/label stable settings memo update should return refreshed report-layout JSON");
        if (asset_path.extension() == ".lbx") {
            expect_contains(update_process.stdout_text, "\"isLabel\": true",
                            "#1826: label stable settings memo update should retain label identity");
        }
        expect_contains(update_process.stdout_text, "\"pageSetupAvailable\": true",
                        "#1826: report/label stable settings memo update should preserve page setup availability");
        expect_contains(update_process.stdout_text, "\"orientationCode\": 1",
                        "#1826: report/label stable settings memo update should refresh orientation codes");
        expect_contains(update_process.stdout_text, "\"paperSizeCode\": 9",
                        "#1826: report/label stable settings memo update should refresh paper-size codes");
        expect_contains(update_process.stdout_text, "\"topMargin\": 14",
                        "#1826: report/label stable settings memo update should refresh top margins");
        expect_contains(update_process.stdout_text, "\"bottomMargin\": 32",
                        "#1826: report/label stable settings memo update should refresh bottom margins");
        expect_contains(update_process.stdout_text, "\"gridVertical\": 6",
                        "#1826: report/label stable settings memo update should refresh vertical grid spacing");
        expect_contains(update_process.stdout_text, "\"gridHorizontal\": 10",
                        "#1826: report/label stable settings memo update should refresh horizontal grid spacing");
        expect_contains(update_process.stdout_text, "\"settingCount\": 7",
                        "#1826: report/label stable settings memo update should preserve memo and field setting counts");
        expect_contains(update_process.stdout_text, "\"selectedReportSettingsAvailable\": true",
                        "#1826: report/label stable settings memo update should preserve selected-settings availability");
        expect_contains(update_process.stdout_text, "\"selectedReportSelectionKind\": \"settings\"",
                        "#1826: report/label stable settings memo update should preserve settings selection kind");
        expect_contains_in_order(
            update_process.stdout_text,
            {
                "\"selectedReportSettings\": [",
                "\"name\": \"ORIENTATION\", \"recordIndex\": 0, \"fieldIndex\": 2, \"sourceLineIndex\": 0",
                "\"name\": \"PAPERSIZE\", \"recordIndex\": 0, \"fieldIndex\": 2, \"sourceLineIndex\": 1",
                "\"name\": \"BOTMARGIN\", \"recordIndex\": 0, \"fieldIndex\": 2, \"sourceLineIndex\": 2",
                "\"name\": \"GRIDV\", \"recordIndex\": 0, \"fieldIndex\": 2, \"sourceLineIndex\": 3",
                "\"name\": \"GRIDH\", \"recordIndex\": 0, \"fieldIndex\": 2, \"sourceLineIndex\": 4",
                "\"name\": \"TOPMARGIN\", \"recordIndex\": 0, \"fieldIndex\": 2, \"sourceLineIndex\": 5",
                "\"name\": \"TOPMARGIN\", \"recordIndex\": 0, \"fieldIndex\": 8, \"sourceLineIndex\": null"
            },
            "#1826: report/label stable settings memo update should refresh selected setting provenance");
    };

    run_settings_update(temp_root / "settings_memo_stable.frx", "settings_memo_stable.frx", "report");
    run_settings_update(temp_root / "settings_memo_stable.lbx", "settings_memo_stable.lbx", "label");

    if (failures == 0) {
        fs::remove_all(temp_root, ignored);
    }
}

