    const fs::path form_path = temp_root / "outline.scx";
    write_synthetic_form_table_for_visual_object_list(form_path);

    const auto list_process = run_process_capture(
        studio_host_path,
        {
            "--visual-object-list",
            "--path", form_path.string(),
            "--json"
        },
        temp_root);
